class Value:
    """A number that remembers how it was made (lesson 6.5)."""
    def __init__(self, data, _prev=(), _op=''):
        self.data = data
        self._prev = set(_prev)
        self._op = _op

    def __repr__(self):
        return f"Value({self.data})"

    def __add__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        return Value(self.data + other.data, (self, other), '+')

    def __mul__(self, other):
        other = other if isinstance(other, Value) else Value(other)
        return Value(self.data * other.data, (self, other), '*')

    def __radd__(self, other):   # other + self, when other is a plain number
        return self + other

    def __rmul__(self, other):   # other * self
        return self * other

def topo_order(root):
    order, visited = [], set()

    def visit(v):
        if v not in visited:
            visited.add(v)
            for child in v._prev:
                visit(child)
            order.append(v)

    visit(root)
    return order
